"use strict";(globalThis.webpackChunkdocs_next=globalThis.webpackChunkdocs_next||[]).push([[56910],{72679(e){e.exports=JSON.parse('{"tag":{"label":"openwebui","permalink":"/docs-next/pr-preview/pr-442/docs/tags/openwebui","allTagsPath":"/docs-next/pr-preview/pr-442/docs/tags","count":2,"items":[{"id":"blueprints/by-use-case/ai/litellm/litellm","title":"Build a Unified LLM Gateway with LiteLLM on CCE","description":"An LLM gateway acts as a centralized entry point for all interactions between applications and large language models. Rather than binding applications to specific model APIs or providers, the gateway introduces a stable interface that abstracts the underlying inference layer. This separation allows platform teams to control how requests are routed, which models are used, and where inference is executed, without requiring changes at the application level. In environments where multiple model backends coexist, such as locally hosted models on GPU infrastructure and external inference services, the gateway becomes the control plane for traffic management, policy enforcement, operational consistency and costs management.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/litellm/litellm"},{"id":"blueprints/by-use-case/ai/litellm/deploy-openwebui-on-cce","title":"Deploy Open WebUI on CCE","description":"Open WebUI is a self-hosted web interface for interacting with large language models. It provides a chat-based UI that connects to OpenAI-compatible APIs, making it easy to test and use different models without building custom frontends. In this blueprint, Open WebUI acts as the user-facing layer on top of the LLM gateway. It allows users and teams to interact with the models exposed through LiteLLM, without needing to know where those models are running. This makes it a practical tool for internal adoption, enabling non-developers and developers alike to access LLM capabilities through a browser.","permalink":"/docs-next/pr-preview/pr-442/docs/blueprints/by-use-case/ai/litellm/deploy-openwebui-on-cce"}],"unlisted":false}}')}}]);